{
  "name": "Agent 1 · Recepční odpovídá na e-maily",
  "nodes": [
    {
      "parameters": {
        "pollTimes": {
          "item": [
            {
              "mode": "everyX",
              "value": 5,
              "unit": "minutes"
            }
          ]
        },
        "simple": true,
        "filters": {
          "labelIds": [
            "INBOX"
          ],
          "readStatus": "unread"
        },
        "options": {}
      },
      "id": "1b30a24c-c30f-46a9-ab98-042a083b37c4",
      "name": "Nový e-mail",
      "type": "n8n-nodes-base.gmailTrigger",
      "typeVersion": 1.2,
      "position": [
        0,
        0
      ],
      "credentials": {
        "gmailOAuth2": {
          "id": "",
          "name": "Gmail account"
        }
      }
    },
    {
      "parameters": {
        "promptType": "define",
        "text": "=Odesílatel: {{ $json.From }}\nPředmět: {{ $json.Subject }}\n\nText e-mailu:\n{{ $json.snippet }}",
        "options": {
          "systemMessage": "Jsi recepční kosmetického salonu [NÁZEV SALONU] v [MĚSTO]. Píšeš odpovědi na e-maily klientek.\n\nPravidla:\n- Piš česky, vykej, vlídně a stručně (max. 6 vět). Podepiš se: Tým [NÁZEV SALONU].\n- Používej jen informace z PODKLADŮ níže. Když odpověď neznáš, napiš, že se ozve kolegyně, a nic si nevymýšlej.\n- Nikdy neslibuj výsledek ošetření a nepiš o léčebných účincích.\n- Na zdravotní dotazy (léky, těhotenství, onemocnění, implantáty) odpověz, že je probereme osobně na konzultaci.\n- Termín nikdy nepotvrzuj sám. Pošli odkaz na online rezervaci.\n- Když e-mail není dotaz klientky (reklama, faktura, newsletter), odpověz jen slovem PRESKOCIT.\n\nPODKLADY:\n[Sem vložte text z dokumentu Mozek salonu: služby, ceny, otevírací doba, adresa, parkování, storno podmínky, odkaz na rezervaci.]"
        }
      },
      "id": "4cd6dd59-042d-4337-8bfe-d6aaf5e8161b",
      "name": "Recepční (AI agent)",
      "type": "@n8n/n8n-nodes-langchain.agent",
      "typeVersion": 1.7,
      "position": [
        260,
        0
      ]
    },
    {
      "parameters": {
        "model": {
          "__rl": true,
          "mode": "list",
          "value": "gpt-4o-mini"
        },
        "options": {
          "temperature": 0.4
        }
      },
      "id": "1d125103-d5c9-4a90-b373-723444b27d1a",
      "name": "OpenAI Chat Model",
      "type": "@n8n/n8n-nodes-langchain.lmChatOpenAi",
      "typeVersion": 1.2,
      "position": [
        260,
        220
      ],
      "credentials": {
        "openAiApi": {
          "id": "",
          "name": "OpenAI account"
        }
      }
    },
    {
      "parameters": {
        "conditions": {
          "options": {
            "caseSensitive": true,
            "leftValue": "",
            "typeValidation": "strict",
            "version": 2
          },
          "conditions": [
            {
              "id": "69bb9d81-3270-4353-a4cf-173d0daef13f",
              "leftValue": "={{ $json.output }}",
              "rightValue": "PRESKOCIT",
              "operator": {
                "type": "string",
                "operation": "notContains"
              }
            }
          ],
          "combinator": "and"
        },
        "options": {}
      },
      "id": "9293259a-b603-45fe-a6d3-70793b1cb46a",
      "name": "Je to dotaz klientky?",
      "type": "n8n-nodes-base.if",
      "typeVersion": 2.2,
      "position": [
        620,
        0
      ]
    },
    {
      "parameters": {
        "resource": "draft",
        "subject": "=Re: {{ $('Nový e-mail').item.json.Subject }}",
        "message": "={{ $json.output }}",
        "options": {
          "threadId": "={{ $('Nový e-mail').item.json.threadId }}",
          "sendTo": "={{ $('Nový e-mail').item.json.From }}"
        }
      },
      "id": "e3593330-9106-44c3-a23f-9fe98db0a331",
      "name": "Uložit koncept odpovědi",
      "type": "n8n-nodes-base.gmail",
      "typeVersion": 2.1,
      "position": [
        880,
        -20
      ],
      "credentials": {
        "gmailOAuth2": {
          "id": "",
          "name": "Gmail account"
        }
      }
    }
  ],
  "connections": {
    "Nový e-mail": {
      "main": [
        [
          {
            "node": "Recepční (AI agent)",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "OpenAI Chat Model": {
      "ai_languageModel": [
        [
          {
            "node": "Recepční (AI agent)",
            "type": "ai_languageModel",
            "index": 0
          }
        ]
      ]
    },
    "Recepční (AI agent)": {
      "main": [
        [
          {
            "node": "Je to dotaz klientky?",
            "type": "main",
            "index": 0
          }
        ]
      ]
