      "main": [
        [
          {
            "node": "Uložit koncept odpovědi",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "settings": {
    "executionOrder": "v1"
  }
}

{
  "name": "Agent 2 · Plán obsahu každé pondělí",
